for (size_t idx = start; idx < end; idx++) {
    // Get current particle
    Particle &pi = particles[idx];

    // Initialize forces to zero
    float fx = 0.0f, fy = 0.0f, fz = 0.0f;

    // Get position of particle i
    float pix = pi.position.x;
    float piy = pi.position.y;
    float piz = pi.position.z;

    // Hash to find bucket in particleTable
    // Need to determine cell index based on position
    // Typically: cell = floor(pos / h)

    // Calculate cell indices for current particle
    int cellX = static_cast<int>(std::floor(pix / h));
    int cellY = static_cast<int>(std::floor(piy / h));
    int cellZ = static_cast<int>(std::floor(piz / h));

    // Iterate through neighboring cells (3x3x3 grid)
    for (int dx = -1; dx <= 1; dx++) {
        for (int dy = -1; dy <= 1; dy++) {
            for (int dz = -1; dz <= 1; dz++) {
                // Calculate neighbor cell index
                int neighborCellX = cellX + dx;
                int neighborCellY = cellY + dy;
                int neighborCellZ = cellZ + dz;

                // Hash neighbor cell to get starting index in particleTable
                // Need to implement hash function for 3D grid
                size_t hash = hashCell(neighborCellX, neighborCellY, neighborCellZ);
                size_t tableIndex = hash % particleCount;

                // Iterate through particles in this cell
                for (size_t j = tableIndex; j < tableIndex + 64 && j < particleCount; j++) {
                    if (particles[j].cellId == hash) {
                        // Calculate distance
                        float dx = particles[j].position.x - pix;
                        float dy = particles[j].position.y - piy;
                        float dz = particles[j].position.z - piz;
                        float r = std::sqrt(dx*dx + dy*dy + dz*dz);

                        if (r < h && r > 0.001f) {
                            // Apply pressure and viscosity forces
                            float pressure = particles[j].pressure;
                            float viscosity = particles[j].viscosity;

                            // Pressure force (repulsive)
                            float pressureForce = -pressure / (r * r);

                            // Viscosity force (attractive)
                            float viscosityForce = viscosity * (particles[j].velocity - pi.velocity) / (r * r);

                            fx += (pressureForce + viscosityForce) * dx / r;
                            fy += (pressureForce + viscosityForce) * dy / r;
                            fz += (pressureForce + viscosityForce) * dz / r;
                        }
                    }
                }
            }
        }
    }

    // Apply calculated forces to particle
    pi.force.x += fx;
    pi.force.y += fy;
    pi.force.z += fz;
}

